package com.ivonix.pulse.ontology.domain;
import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Service; import java.util.*;
@Service public class RoboticsService extends DomainDataService { public RoboticsService(JdbcTemplate j){super(j,"robotics_data",Set.of("joint_positions","joint_torques","end_effector_pose"));} public DomainDiagnosticResult diagnose(UUID d,UUID o){var x=latest(d,o,1);return new DomainDiagnosticResult("robotics",x.isEmpty()?"No telemetry available":"Joint state captured; torque deviation requires calibrated limits",x.isEmpty()?.10:.55,List.of("Validate joint torque limits","Check calibration"));}}